// Split the lister's rows into one item per proposal so the next node
// records each proposal's outcome per-item.
const r = $input.first() ? $input.first().json : null;
const arr = Array.isArray(r) ? r : (Array.isArray(r && r.data) ? r.data : (r ? [r] : []));
return arr.filter((x) => x && x.proposal_id).map((x) => ({ json: x }));

// Fingerprint the measured proposal outcome for the immutable ledger (OPANCHOR).
// ⛔ The dispatcher edge_blockchain_audit knows insert_record (same as the deploy and
// PKI producers); the former 'proposal_outcome_anchor' action never existed, so every
// run's anchor failed silently (fail-open). Only the decision is anchored — the
// 'outcome' phase (score_before/after, delta, rollback proposal) — not the baseline
// snapshot nor skipped/unscoped items.
const crypto = require('crypto');
const out = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.phase !== 'outcome' || !r.proposal_id) continue;
  const payload = { event: 'improvement_proposal_outcome', proposal_id: r.proposal_id, outcome: r, at: new Date().toISOString() };
  const payload_hash = crypto.createHash('sha256').update(JSON.stringify(payload)).digest('hex');
  out.push({ json: { event_type: 'improvement_proposal', reference_table: 'improvement_proposals', reference_id: String(r.proposal_id), payload, payload_hash } });
}
return out;
